#include "symm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization, translated from the original C version.
 *
 * Original C signature:
 *   void init_array(int m, int n,
 *                   DATA_TYPE *alpha,
 *                   DATA_TYPE *beta,
 *                   DATA_TYPE C[M][N],
 *                   DATA_TYPE A[M][M],
 *                   DATA_TYPE B[M][N]);
 *
 * Mapping:
 *   - C[i][j] (MxN) -> Buffer C(j, i) with shape (n, m)
 *   - B[i][j] (MxN) -> Buffer B(j, i) with shape (n, m)
 *   - A[i][j] (MxM) -> Buffer A(j, i) with shape (m, m)
 */
static
void init_array(int m, int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // Initialize C and B:
    //
    // C[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    // B[i][j] = (DATA_TYPE)((n + i - j) % 100) / m;
    //
    // With our Buffer layout C(j, i), B(j, i):
    Func init_C("init_C"), init_B("init_B");

    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // Initialize A:
    //
    // for (i = 0; i < m; i++) {
    //   for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    //   for (j = i+1; j < m; j++)
    //       A[i][j] = -999;
    // }
    //
    // We store A[i][j] at A(j, i), and fill the "unused" upper part with -999.
    Func init_A("init_A");
    Expr lower_tri = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    Expr unused    = cast<num_t>(-999);
    init_A(j, i)   = select(j <= i, lower_tri, unused);

    // ------------------------------------------------------------------
    // Scheduling for initialization
    //
    // The initialization is done once but touches O(m*n) or O(m*m) data.
    // We:
    //   - vectorize across j (contiguous in memory),
    //   - parallelize across i (independent rows).
    // ------------------------------------------------------------------
    Target init_target = get_jit_target_from_environment();
    int vec_init = init_target.natural_vector_size(type_of<num_t>());
    if (vec_init <= 0) {
        vec_init = 8; // reasonable fallback
    }

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_init);

    init_B
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_init);

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_init);

    // Realize into the provided buffers
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from symm.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C, B : MxN  -> (n, m) in Halide
    //   A    : MxM  -> (m, m) in Halide
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // Vars and reduction domain
    Var i("i"), j("j");
    // A is MxM stored as A(j, i); extent of dim(0) is m
    RDom k(0, A.dim(0).extent(), "k");

    // Main computational kernel in Halide.
    //
    // Original BLAS semantics:
    //   C := alpha * A * B + beta * C
    // with A symmetric, stored in its lower triangular part.
    //
    // We construct a symmetric view of A:
    //   A_sym(i, l) =
    //      (l <= i) ? A(i, l)  : A(l, i)
    //
    // Remember our Buffer mapping:
    //   original A[i][l] -> A_param(l, i)
    //   original A[l][i] -> A_param(i, l)
    //
    // So we define:
    //   A_sym(i, k) = (k <= i) ? A_param(k, i) : A_param(i, k)
    //
    // Then:
    //   symm(j, i) = beta * C_param(j, i)
    //   symm(j, i) += alpha * sum_k A_sym(i, k) * B_param(j, k)
    //
    Func symm("symm");

    Expr beta_e  = cast<num_t>(beta);
    Expr alpha_e = cast<num_t>(alpha);

    // Base: beta * C
    symm(j, i) = beta_e * C_param(j, i);

    // Symmetric access to A
    Expr A_sym = select(k <= i, A_param(k, i), A_param(i, k));

    // Accumulate alpha * A_sym * B
    symm(j, i) += alpha_e * A_sym * B_param(j, k);

    // ------------------------------------------------------------------
    // Scheduling for the SYMM kernel
    //
    // Buffers:
    //   - dimension 0 (j) is contiguous in memory for C and B,
    //     so we vectorize over j.
    //   - dimension 1 (i) is the slow/row dimension, good for
    //     parallelization and tiling.
    //
    // We use:
    //   - compute_root for the entire symm Func,
    //   - tiling over (j, i) for better cache locality,
    //   - parallelization over tiles in i (rows),
    //   - vectorization over inner j within each tile,
    //   - matching schedule for the update (reduction) stage.
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 8; // safe fallback if vector width is unknown
    }

    // Make sure we don't vectorize beyond the tile width
    const int tile_j = 64;   // columns per tile (along j)
    const int tile_i = 32;   // rows per tile (along i)
    vec_width = std::min(vec_width, tile_j);

    Var jo("jo"), ji("ji"), io("io"), ii("ii");

    // Compute symm at the root level (like a GEMM)
    symm.compute_root();

    // Provide explicit bounds to help the compiler
    symm.bound(j, 0, n)
        .bound(i, 0, m);

    // Tile the (j, i) space: j fastest (contiguous), i slower (rows)
    // After this, the loop nest is roughly:
    // for io (outer tiles in i)
    //   for jo (outer tiles in j)
    //     for ii (rows inside tile)
    //       for ji (cols inside tile, contiguous)
    symm.tile(j, i, jo, io, ji, ii, tile_j, tile_i);

    // Parallelize across tiles along the i dimension (rows). This
    // typically gives good scaling on multi-core CPUs.
    symm.parallel(io);

    // Vectorize the innermost j-loop (contiguous memory).
    symm.vectorize(ji, vec_width);

    // Now schedule the update (reduction) stage to match the tiling.
    //
    // After the tile() call, the reduction stage has loop vars:
    //   io, jo, ii, ji, k
    //
    // We reorder to:
    //   io (outer, parallel)
    //   jo
    //   ii
    //   k
    //   ji (innermost, vectorized)
    //
    // For each (i, j) pair we still sum over all k, just in a
    // different loop nesting order; this preserves the mathematical
    // result and improves memory locality and SIMD utilization.
    symm.update()
        .reorder(ji, k, ii, jo, io)  // ji innermost; k just outside ji
        .parallel(io)
        .vectorize(ji, vec_width);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel
    symm.compile_jit();

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(ii, jj) in C layout is C(jj, ii) in our Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
